```

```javascript
// Minimal hook and usage sketch
export function useOnboardingStep(initial = 0) {
  const [step, setStep] = React.useState(initial)
  function next() { setStep((s) => Math.min(2, s + 1)) }
  function skip() { setStep(2) }
  const isLast = step === 2
  return { step, next, skip, isLast }
}
